import sys

def main():
    data = sys.stdin.read().split()
    s, p = data[0], data[1]
    n, m = len(s), len(p)
    res = []
    if m <= n:
        need = [0] * 26
        for ch in p:
            need[ord(ch) - 97] += 1
        have = [0] * 26
        for i in range(n):
            have[ord(s[i]) - 97] += 1
            if i >= m:
                have[ord(s[i - m]) - 97] -= 1
            if i >= m - 1 and have == need:
                res.append(i - m + 1)
    print(' '.join(map(str, res)) if res else -1)

